const raw = $json.choices?.[0]?.message?.content;
if (!raw) throw new Error('Model response did not contain message content');
let result;
try { result = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (error) { throw new Error(`Model returned invalid JSON: ${error.message}`); }
if (!Array.isArray(result.findings) || !Array.isArray(result.limitations)) throw new Error('Result does not match the minimum finding contract');
for (const finding of result.findings) {
  if (!Array.isArray(finding.evidence) || finding.evidence.length === 0) throw new Error('Rejected unsupported finding with no evidence citation');
}
return [{ json: result }];
